/* From Uiverse.io by Yaya12085 - Tags: form */
.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 300px;
  background-color: #fff;
  border-radius: 20px;
  padding: 30px 20px;
  box-shadow: 100px 100px 80px rgba(0, 0, 0, 0.03)
}

.__UIV_SCOPE__ .title {
  color: black;
  font-weight: bold;
  text-align: center;
  font-size: 20px;
  margin-bottom: 4px;
}

.__UIV_SCOPE__ .sub {
  text-align: center;
  color: black;
  font-size: 14px;
  width: 100%;
}

.__UIV_SCOPE__ .sub.mb {
  margin-bottom: 1px;
}

.__UIV_SCOPE__ .sub a {
  color: rgb(23, 111, 211);
}

.__UIV_SCOPE__ .avatar {
  height: 50px;
  width: 50px;
  background-color: rgb(23, 111, 211);
  border-radius: 50%;
  align-self: center;
  padding: 6px;
  cursor: pointer;
  box-shadow: 12.5px 12.5px 10px rgba(0, 0, 0, 0.015),100px 100px 80px rgba(0, 0, 0, 0.03);
}

.__UIV_SCOPE__ .form button {
  align-self: flex-end;
}

.__UIV_SCOPE__ .input, .__UIV_SCOPE__ button {
  border: none;
  outline: none;
  width: 100%;
  padding: 16px 10px;
  background-color: rgb(247, 243, 243);
  border-radius: 10px;
  box-shadow: 12.5px 12.5px 10px rgba(0, 0, 0, 0.015),100px 100px 80px rgba(0, 0, 0, 0.03);
}

.__UIV_SCOPE__ button {
  margin-top: 12px;
  background-color: rgb(23, 111, 211);
  color: #fff;
  text-transform: uppercase;
  font-weight: bold;
}

.__UIV_SCOPE__ .input:focus {
  border: 1px solid rgb(23, 111, 211);
}

.__UIV_SCOPE__ #file {
  display: none;
}
